    coords.erase(unique(coords.begin(), coords.end()), coords.end());
    int m = coords.size();
    vector<int> tree(m + 1, 0);
    vector<char> placed(m, 0);
    auto rank = [&](long long x) { return int(lower_bound(coords.begin(), coords.end(), x) - coords.begin()); };
