import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static long[] coords;
    static int m;
    static int[] tree;

    static int rank(long x) {
        int lo = 0, hi = m;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (coords[mid] < x) lo = mid + 1; else hi = mid; }
        return lo;
    }

    static int prefix(int end) {
        int r = 0;
        for (; end > 0; end -= end & -end) r += tree[end];
        return r;
    }

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        long[][] ops = new long[q][3];
        long[] all = new long[q];
        int cnt = 0;
        for (long[] op : ops) {
            op[0] = nextLong();
            op[1] = nextLong();
            if (op[0] == 1) all[cnt++] = op[1];
            else op[2] = nextLong();
        }
        Arrays.sort(all, 0, cnt);
        coords = new long[cnt];
        for (int i = 0; i < cnt; i++) if (i == 0 || all[i] != all[i - 1]) coords[m++] = all[i];
        tree = new int[m + 1];
        boolean[] placed = new boolean[m];
        StringBuilder sb = new StringBuilder();
        for (long[] op : ops) {
            if (op[0] == 1) {
                int i = rank(op[1]);
                if (placed[i]) continue;
                placed[i] = true;
                for (int j = i + 1; j <= m; j += j & -j) tree[j]++;
            } else {
                // obstacles with coordinate in [x - size, x)
                sb.append(prefix(rank(op[1])) == prefix(rank(op[1] - op[2])) ? '1' : '0');
            }
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	q := readInt()
	ops := make([][3]int, q)
	var coords []int
	for i := range ops {
		ops[i][0], ops[i][1] = readInt(), readInt()
		if ops[i][0] == 1 {
			coords = append(coords, ops[i][1])
		} else {
			ops[i][2] = readInt()
		}
	}
	sort.Ints(coords)
	m := 0
	for i, c := range coords {
		if i == 0 || c != coords[i-1] {
			coords[m] = c
			m++
		}
	}
	coords = coords[:m]
	tree := make([]int, m+1)
	placed := make([]bool, m)
	prefix := func(end int) int {
		r := 0
		for ; end > 0; end -= end & -end {
			r += tree[end]
		}
		return r
	}
	ans := make([]byte, 0, q)
	for _, op := range ops {
		if op[0] == 1 {
			i := sort.SearchInts(coords, op[1])
			if placed[i] {
				continue
			}
			placed[i] = true
			for j := i + 1; j <= m; j += j & -j {
				tree[j]++
			}
		} else if prefix(sort.SearchInts(coords, op[1])) == prefix(sort.SearchInts(coords, op[1]-op[2])) {
			// no obstacle with coordinate in [x - size, x)
			ans = append(ans, '1')
		} else {
			ans = append(ans, '0')
		}
	}
	fmt.Println(string(ans))
}
